<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Ubuntu Desktop Clone</title>
    <style>
        :root {
            --ubuntu-orange: #e95420;
            --ubuntu-purple: #300a24;
            --ubuntu-dark: #2c001e;
            --window-bg: #3d3d3d;
            --window-header: #2d2d2d;
            --text-color: #eeeeee;
        }

        * { box-sizing: border-box; }

        body, html {
            margin: 0;
            padding: 0;
            width: 100%;
            height: 100%;
            overflow: hidden;
            font-family: sans-serif;
        }

        #desktop {
            width: 100vw;
            height: 100vh;
            background: linear-gradient(135deg, var(--ubuntu-purple) 0%, var(--ubuntu-dark) 100%);
            position: relative;
            overflow: hidden;
        }

        /* Taskbar/Dock */
        #taskbar {
            position: absolute;
            bottom: 15px;
            left: 50%;
            transform: translateX(-50%);
            height: 60px;
            background: rgba(0, 0, 0, 0.7);
            backdrop-filter: blur(10px);
            border-radius: 15px;
            padding: 0 15px;
            display: flex;
            align-items: center;
            gap: 20px;
            z-index: 1000;
            border: 1px solid rgba(255, 255, 255, 0.1);
        }

        .launcher-btn {
            width: 45px;
            height: 45px;
            background: #444;
            border-radius: 8px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: transform 0.2s, background 0.2s;
            font-size: 24px;
            user-select: none;
        }

        .launcher-btn:hover {
            transform: scale(1.1);
            background: #555;
        }

        /* Window Styling */
        .window {
            position: absolute;
            min-width: 360px;
            min-height: 240px;
            background: var(--window-bg);
            border-radius: 8px;
            box-shadow: 0 15px 35px rgba(0,0,0,0.5);
            display: none;
            flex-direction: column;
            overflow: hidden;
            border: 1px solid #555;
        }

        .title-bar {
            background: var(--window-header);
            padding: 8px 12px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            cursor: move;
            user-select: none;
        }

        .title-text {
            color: var(--text-color);
            font-size: 0.9rem;
            font-weight: bold;
        }

        .win-close {
            width: 14px;
            height: 14px;
            background: #e74c3c;
            border-radius: 50%;
            cursor: pointer;
            border: none;
        }

        .win-close:hover { background: #ff5e4d; }

        /* Files App UI */
        #files-content {
            flex: 1;
            padding: 10px;
            overflow-y: auto;
            color: var(--text-color);
        }

        #files-nav {
            padding: 5px 10px;
            background: #333;
            display: flex;
            align-items: center;
            gap: 8px;
            border-bottom: 1px solid #444;
        }

        #files-path {
            font-family: monospace;
            color: var(--ubuntu-orange);
            font-size: 0.9rem;
            flex: 1;
        }

        #files-up {
            cursor: pointer;
            background: #555;
            border: none;
            color: white;
            padding: 2px 8px;
            border-radius: 3px;
            font-size: 0.8rem;
        }

        .fs-item {
            padding: 6px 10px;
            cursor: pointer;
            border-radius: 4px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .fs-item:hover { background: rgba(255, 255, 255, 0.1); }

        /* Notepad App UI */
        #notepad-container {
            display: flex;
            flex-direction: column;
            height: 100%;
        }

        #tabs {
            background: #222;
            display: flex;
            align-items: flex-end;
            padding: 5px 5px 0 5px;
            gap: 2px;
            border-bottom: 1px solid #444;
        }

        .tab {
            background: #333;
            color: #aaa;
            padding: 6px 12px;
            border-radius: 5px 5px 0 0;
            cursor: pointer;
            font-size: 0.85rem;
            user-select: none;
        }

        .tab.active {
            background: var(--window-bg);
            color: white;
        }

        #new-tab {
            padding: 4px 10px;
            cursor: pointer;
            background: transparent;
            border: none;
            color: white;
            font-size: 1.2rem;
            margin-bottom: 3px;
        }

        #editor {
            flex: 1;
            width: 100%;
            background: var(--window-bg);
            border: none;
            color: #ddd;
            padding: 15px;
            resize: none;
            font-family: monospace;
            outline: none;
        }

    </style>
</head>
<body>

<div id="desktop">
    <!-- Taskbar -->
    <div id="taskbar">
        <div class="launcher-btn" id="open-files" title="Files">📁</div>
        <div class="launcher-btn" id="open-notepad" title="Notepad">📝</div>
    </div>

    <!-- Files Window -->
    <div id="files-window" class="window" style="top: 100px; left: 150px;">
        <div class="title-bar">
            <span class="title-text">Files</span>
            <button class="win-close"></button>
        </div>
        <div id="files-nav">
            <button id="files-up">UP</button>
            <div id="files-path">/</div>
        </div>
        <div id="files-content">
            <!-- File items injected here -->
        </div>
    </div>

    <!-- Notepad Window -->
    <div id="notepad-window" class="window" style="top: 80px; left: 400px;">
        <div class="title-bar">
            <span class="title-text">Notepad</span>
            <button class="win-close"></button>
        </div>
        <div id="notepad-container">
            <div id="tabs">
                <!-- Tabs injected here -->
                <button id="new-tab">+</button>
            </div>
            <textarea id="editor" spellcheck="false"></textarea>
        </div>
    </div>
</div>

<script>
    // --- Filesystem Data ---
    const fsData = {
        name: '/', type: 'dir', children: {
            'bin': { type: 'dir', children: {} },
            'etc': { type: 'dir', children: {} },
            'home': { type: 'dir', children: {
                'user': { type: 'dir', children: {
                    'Documents': { type: 'dir', children: {
                        'notes.txt': { type: 'file', content: 'Important notes...' },
                        'todo.txt': { type: 'file', content: 'Buy groceries\nFix bug' }
                    }},
                    'Downloads': { type: 'dir', children: {} },
                    'Pictures': { type: 'dir', children: {} }
                }}
            }},
            'usr': { type: 'dir', children: {} },
            'var': { type: 'dir', children: {} }
        }
    };

    // --- State Management ---
    let currentPathArr = []; // Root is []
    let notepadTabs = [];
    let activeTabId = null;

    // --- Window Management (Draggable & Close) ---
    function initWindows() {
        document.querySelectorAll('.window').forEach(win => {
            const closeBtn = win.querySelector('.win-close');
            const titleBar = win.querySelector('.title-bar');

            closeBtn.onclick = (e) => {
                e.stopPropagation();
                win.style.display = 'none';
            };

            // Draggable logic
            let pos1 = 0, pos2 = 0, pos3 = 0, pos4 = 0;
            titleBar.onmousedown = (e) => {
                e.preventDefault();
                pos3 = e.clientX;
                pos4 = e.clientY;
                document.onmouseup = () => {
                    document.onmouseup = null;
                    document.onmousemove = null;
                };
                document.onmousemove = (e) => {
                    e.preventDefault();
                    pos1 = pos3 - e.clientX;
                    pos2 = pos4 - e.clientY;
                    pos3 = e.clientX;
                    pos4 = e.clientY;
                    win.style.top = (win.offsetTop - pos2) + "px";
                    win.style.left = (win.offsetLeft - pos1) + "px";
                };
                // Bring to front
                document.querySelectorAll('.window').forEach(w => w.style.zIndex = 1);
                win.style.zIndex = 10;
            };
        });

        document.getElementById('open-files').onclick = () => {
            const win = document.app.document.getElementById('files-window'); // error in ref? No, use direct:
            document.getElementById('files-window').style.display = 'flex';
            bringToFront('files-window');
        };

        document.getElementById('open-notepad').onclick = () => {
            document.getElementById('notepad-window').style.display = 'flex';
            bringToFront('notepad-window');
        };
    }

    function bringToFront(id) {
        document.querySelectorAll('.window').forEach(w => w.style.zIndex = 1);
        document.getElementById(id).style.zIndex = 10;
    }

    // --- Files App Logic ---
    function getDirAt(arr) {
        let curr = fsData;
        for (const part of arr) {
            curr = curr.children[part];
        }
        return curr;
    }

    function renderFiles() {
        const container = document.getElementById('files-content');
        const pathEl = document.getElementById('files-path');
        const upBtn = document.getElementById('files-up');

        pathEl.innerText = '/' + currentPathArr.join('/');
        upBtn.style.visibility = currentPathArr.length === 0 ? 'hidden' : 'visible';

        container.innerHTML = '';
        const dir = getDirAt(currentPathArr);

        // Sort: dirs first, then files
        const keys = Object.keys(dir.children).sort((a, b) => {
            const aIsDir = dir.children[a].type === 'dir';
            const bIsDir = dir.children[b].type === 'dir';
            if (aIsDir && !bIsDir) return -1;
            if (!aIsDir && bIsDir) return 1;
            return a.localeCompare(b);
        });

        keys.forEach(name => {
            const item = document.createElement('div');
            item.className = 'fs-item';
            const isDir = dir.children[name].type === 'dir';
            item.innerText = (isDir ? '📁 ' : '📄 ') + name;

            item.ondblclick = () => {
                if (isDir) {
                    currentPathArr.push(name);
                    renderFiles();
                }
            };
            container.appendChild(item);
        });
    }

    document.getElementById('files-up').onclick = () => {
        currentPathArr.pop();
        renderFiles();
    };

    // --- Notepad App Logic ---
    const editor = document.getElementById('editor');
    const tabsContainer = document.getElementById('tabs');

    function loadTabs() {
        const saved = localStorage.getItem('desktop_notepad_tabs');
        if (saved) {
            try {
                const parsed = JSON.parse(saved);
                if (Array.isArray(parsed) && parsed.length > 0) {
                    notepadTabs = parsed;
                    activeTabId = parsed[0].id;
                } else {
                    throw new Error();
                }
            } catch (e) {
                createDefaultTabs();
            }
        } else {
            createDefaultTabs();
        }
        renderNotepadTabs();
    }

    function createDefaultTabs() {
        const id = Date.now();
        notepadTabs = [{ id, name: 'Untitled', content: '' }];
        activeTabId = id;
    }

    function saveTabs() {
        localStorage.set('desktop_notepad_tabs', JSON.stringify(notepadTabs)); // wait typo in logic? No, localStorage.setItem
    }

    // Fixed version of saveTabs to use correct API
    function persist() {
        localStorage.setItem('desktop_notepad_tabs', JSON.stringify(notepadTabs));
    }

    function renderNotepadTabs() {
        // Clear existing except the "+" button
        const newTabBtn = document.getElementById('new-tab');
        tabsContainer.innerHTML = '';
        tabsContainer.appendChild(newTabBtn);

        notepadTabs.forEach(tab => {
            const el = document.createElement('div');
            el.className = 'tab' + (tab.id === activeTabId ? ' active' : '');
            el.innerText = tab.name;
            el.onclick = () => switchTab(tab.id);
            tabsContainer.appendChild(el);
        });

        // Update editor content
        const activeTab = notepadTabs.find(t => t.id === activeTabId);
        editor.value = activeTab ? activeTab.content : '';
    }

    function switchTab(id) {
        activeTabId = id;
        renderNotepadTabs();
    }

    document.getElementById('new-tab').onclick = () => {
        const id = Date.now();
        notepadTabs.push({ id, name: 'New Tab', content: '' });
        activeTabId = id;
        renderNotepadTokens(); // Error in my scratchpad? Should be renderNotepadTabs
        // Correcting...
        renderNotepadTabs();
        persist();
    };

    // Redefining the "+" click to avoid scope issues in logic above
    document.getElementById('new-tab').addEventListener('click', () => {
        const id = Date.now();
        notepadTabs.push({ id, name: 'New Tab', content: '' });
        activeTabId = id;
        renderNotepadTabs();
        persist();
    });

    editor.oninput = (e) => {
        const tab = notepadTabs.find(t => t.id === activeTabId);
        if (tab) {
            tab.content = e.target.value;
            persist();
        }
    };

    // Initialize everything
    window.onload = () => {
        initWindows();
        renderFiles();
        loadTabs();
    };

</script>

</body>
</html>
